import React, { useEffect, useState, useMemo } from "react";
import { Canvas } from "@react-three/fiber";
import { MapControls, Text, Line } from "@react-three/drei";
import * as THREE from "three";

// Debug logging - only logs in development mode
const isDev = process.env.NODE_ENV === "development";
const debugLog = (...args) => isDev && console.log(...args);
const debugWarn = (...args) => isDev && console.warn(...args);

// The hardcoded 'yourAirtableData' has been removed.

/**
 * Processes raw data from Airtable into the format needed for the graph.
 * @param {Array<Object>} records - An array of records from Airtable.
 * @returns {Object} - An object containing arrays of nodes and links.
 */

const processAirtableData = (records) => {
  debugLog("Starting processAirtableData with", records.length, "records.");

  const domains = new Map();
  const processes = new Map();
  const nodes = [];
  const links = [];

  debugLog("Starting first pass to build data maps...");

  records.forEach((record, index) => {
    debugLog(`Processing record #${index + 1}`);

    if (record.Domain && record.Process && record.System) {
      const domainName = record.Domain;
      const processName = record.Process;
      const systemName = record.System;

      if (!domains.has(domainName)) {
        domains.set(domainName, {
          name: domainName,
          description: record["Description (from Domain)"],
          processes: new Set(),
          recordId: record.DomainRecordId,
        });
      }
      domains.get(domainName).processes.add(processName);

      if (!processes.has(processName)) {
        processes.set(processName, {
          name: processName,
          description: record["Description (from Process)"],
          domain: domainName,
          systems: new Set(),
          recordId: record.ProcessRecordId,
        });
      }

      processes.get(processName).systems.add({
        name: systemName,
        description: record["Description (from System)"],
        recordId: record.SystemRecordId,
      });
    } else {
      debugWarn(
        `Skipping record #${index + 1} due to missing Domain, Process, or System.`
      );
    }
  });

  debugLog("First pass complete. Found", domains.size, "domains and", processes.size, "processes.");
  debugLog("Starting second pass to create graph nodes...");

  // The rest of the function remains the same...
  const overallGrid = { cols: 2, colWidth: 450, rowHeight: 450, gap: 50 };
  const padding = 25;
  const yLevels = { domain: 0, process_tile: 0.5 };

  Array.from(domains.values()).forEach((domain, i) => {
    const gridX = i % overallGrid.cols;
    const gridY = Math.floor(i / overallGrid.cols);
    const domainX =
      gridX * (overallGrid.colWidth + overallGrid.gap) -
      (overallGrid.colWidth * (overallGrid.cols - 1)) / 2;
    const domainZ = gridY * (overallGrid.rowHeight + overallGrid.gap);

    nodes.push({
      ...domain,
      id: `domain_${domain.name}`,
      fx: domainX,
      fy: yLevels.domain,
      fz: domainZ,
      type: "domain",
      color:
        i % 2 === 0 ? "rgba(234, 209, 220, 0.8)" : "rgba(208, 226, 242, 0.8)",
      width: overallGrid.colWidth,
      height: overallGrid.rowHeight,
      label: domain.name,
    });

    const processesInDomain = Array.from(domain.processes);
    const processGridCols = Math.ceil(Math.sqrt(processesInDomain.length));
    const processGridRows = Math.ceil(
      processesInDomain.length / processGridCols
    );
    const availableWidth = overallGrid.colWidth - padding * 2;
    const availableHeight = overallGrid.rowHeight - padding * 2 - 30;
    const processWidth =
      (availableWidth - padding * (processGridCols - 1)) / processGridCols;
    const processHeight =
      (availableHeight - padding * (processGridRows - 1)) / processGridRows;

    processesInDomain.forEach((procName, j) => {
      const proc = processes.get(procName);
      if (!proc) {
        debugWarn(`Could not find process details for '${procName}'`);
        return; // Skip this iteration if process is not found
      }
      const pGridX = j % processGridCols;
      const pGridY = Math.floor(j / processGridCols);
      const processX =
        domainX -
        availableWidth / 2 +
        pGridX * (processWidth + padding) +
        processWidth / 2;
      const processZ =
        domainZ -
        availableHeight / 2 +
        pGridY * (processHeight + padding) +
        processHeight / 2;

      nodes.push({
        ...proc,
        id: `process_${proc.name}`,
        fx: processX,
        fy: yLevels.process_tile,
        fz: processZ,
        type: "process",
        color: "rgba(255, 255, 255, 0.9)",
        width: processWidth,
        height: processHeight,
        label: proc.name,
      });

      const centralProcessId = `central_process_${proc.name}`;
      nodes.push({
        ...proc,
        id: centralProcessId,
        fx: processX,
        fy: yLevels.process_tile + 15 / 2,
        fz: processZ,
        type: "central_process",
        height: 15,
      });

      const systemsInProcess = Array.from(proc.systems);
      const radius = Math.min(processWidth, processHeight) / 3;

      systemsInProcess.forEach((sys, k) => {
        const angle = (k / systemsInProcess.length) * 2 * Math.PI;
        const systemX = processX + radius * Math.cos(angle);
        const systemZ = processZ + radius * Math.sin(angle);
        const systemId = `system_${sys.name}_${proc.name}`;
        const systemHeight = 16;
        const systemNode = {
          ...sys,
          id: systemId,
          name: sys.name,
          fx: systemX,
          fy: yLevels.process_tile + systemHeight / 2,
          fz: systemZ,
          type: "system",
          label: sys.name,
          height: systemHeight,
        };
        nodes.push(systemNode);
        nodes.push({
          ...systemNode,
          id: `label_${systemId}`,
          fy: yLevels.process_tile + 0.1,
          fz: systemZ + 25,
          type: "system_label",
        });
        links.push({ source: centralProcessId, target: systemId });
      });
    });
  });

  debugLog("Second pass complete.");
  debugLog("Final processed nodes count:", nodes.length);
  debugLog("Final processed links count:", links.length);

  return { nodes, links };
};

// Component for the rounded rectangle panels (domains and processes)
const Panel = ({ node }) => {
  // This component remains exactly the same.
  const texture = useMemo(() => {
    const canvas = document.createElement("canvas");
    const scale = 4;
    canvas.width = node.width * scale;
    canvas.height = node.height * scale;
    const context = canvas.getContext("2d");

    context.fillStyle = node.color;
    context.beginPath();
    context.moveTo(10 * scale, 0);
    context.lineTo(canvas.width - 10 * scale, 0);
    context.quadraticCurveTo(canvas.width, 0, canvas.width, 10 * scale);
    context.lineTo(canvas.width, canvas.height - 10 * scale);
    context.quadraticCurveTo(
      canvas.width,
      canvas.height,
      canvas.width - 10 * scale,
      canvas.height
    );
    context.lineTo(10 * scale, canvas.height);
    context.quadraticCurveTo(0, canvas.height, 0, canvas.height - 10 * scale);
    context.lineTo(0, 10 * scale);
    context.quadraticCurveTo(0, 0, 10 * scale, 0);
    context.closePath();
    context.fill();

    context.strokeStyle = "rgba(0,0,0,0.15)";
    context.lineWidth = 1 * scale;
    context.stroke();

    const fontSize = (node.type === "domain" ? 12 : 10) * scale;
    context.font = `Bold ${fontSize}px Poppins`;
    context.textAlign = "left";
    context.textBaseline = "top";
    context.fillStyle = "#111111";
    const labelX = (node.type === "domain" ? 15 : 10) * scale;
    const labelY =
      node.type === "domain" ? canvas.height - 30 * scale : 10 * scale;
    context.fillText(node.label, labelX, labelY);

    return new THREE.CanvasTexture(canvas);
  }, [node]);

  return (
    <mesh rotation-x={-Math.PI / 2}>
      <planeGeometry args={[node.width, node.height]} />
      <meshBasicMaterial map={texture} transparent opacity={0.9} />
    </mesh>
  );
};

// Main Scene Component - Renders all nodes and links
const GraphScene = ({ graphData, onNodeClick }) => {
  // This component remains exactly the same.
  const { nodes, links } = graphData;

  const nodeMap = useMemo(
    () => new Map(nodes.map((node) => [node.id, node])),
    [nodes]
  );

  const sideTexture = useMemo(() => {
    const canvas = document.createElement("canvas");
    canvas.width = 64;
    canvas.height = 128;
    const context = canvas.getContext("2d");
    context.fillStyle = "#808080";
    context.fillRect(0, 0, 64, 128);
    context.strokeStyle = "black";
    context.lineWidth = 8;
    for (let i = 0; i < 3; i++) {
      context.beginPath();
      context.moveTo(0, canvas.height * (0.25 + i * 0.25));
      context.lineTo(64, canvas.height * (0.25 + i * 0.25));
      context.stroke();
    }
    return new THREE.CanvasTexture(canvas);
  }, []);

  return (
    <>
      {nodes.map((node) => {
        switch (node.type) {
          case "domain":
          case "process":
            return (
              <group
                key={node.id}
                position={[node.fx, node.fy, node.fz]}
                onPointerDown={(e) => {
                  e.stopPropagation();
                  onNodeClick(node);
                }}
              >
                <Panel node={node} />
              </group>
            );
          case "central_process":
            const hexGeometry = new THREE.CylinderGeometry(
              12,
              12,
              node.height,
              6
            );
            const edges = new THREE.EdgesGeometry(hexGeometry);
            return (
              <group
                key={node.id}
                position={[node.fx, node.fy, node.fz]}
                onPointerDown={(e) => {
                  e.stopPropagation();
                  onNodeClick(node);
                }}
              >
                <mesh geometry={hexGeometry}>
                  <meshStandardMaterial color="black" roughness={0.5} />
                </mesh>
                <lineSegments geometry={edges} position={[0, 0.1, 0]}>
                  <lineBasicMaterial color="white" linewidth={2} />
                </lineSegments>
              </group>
            );
          case "system":
            return (
              <mesh
                key={node.id}
                position={[node.fx, node.fy, node.fz]}
                onPointerDown={(e) => {
                  e.stopPropagation();
                  onNodeClick(node);
                }}
              >
                <cylinderGeometry args={[12, 12, node.height, 32]} />
                <meshStandardMaterial attach="material-0" map={sideTexture} />
                <meshStandardMaterial attach="material-1" color="#808080" />
                <meshStandardMaterial attach="material-2" color="#808080" />
              </mesh>
            );
          case "system_label":
            return (
              <Text
                key={node.id}
                position={[node.fx, node.fy, node.fz]}
                fontSize={8}
                color="#333333"
                anchorX="center"
                anchorY="middle"
                rotation-x={-Math.PI / 2}
                font={`${process.env.PUBLIC_URL}/Poppins-Medium.ttf`}
              >
                {node.label}
              </Text>
            );
          default:
            return null;
        }
      })}

      {links.map((link, i) => {
        const sourceNode = nodeMap.get(link.source);
        const targetNode = nodeMap.get(link.target);
        if (!sourceNode || !targetNode) return null;

        return (
          <Line
            key={i}
            points={[
              [sourceNode.fx, sourceNode.fy, sourceNode.fz],
              [targetNode.fx, targetNode.fy, targetNode.fz],
            ]}
            color="black"
            lineWidth={1.5}
          />
        );
      })}
    </>
  );
};

// Validate Airtable record IDs (format: rec + 14 alphanumeric chars)
const isValidRecordId = (id) => /^rec[A-Za-z0-9]{14}$/.test(id);

// Pop-up Modal Component
const InfoPopup = ({ node, onClose }) => {
  const getSoftrUrl = () => {
    // Validate recordId before using in URL to prevent injection
    if (!node.recordId || !isValidRecordId(node.recordId)) {
      return "#";
    }
    const baseUrl = "https://cortex-knowledge-hub.softr.app";
    switch (node.type) {
      case "domain":
        return `${baseUrl}/domain-details?recordId=${node.recordId}`;
      case "process":
      case "central_process":
        return `${baseUrl}/process-details?recordId=${node.recordId}`;
      case "system":
        return `${baseUrl}/system-details?recordId=${node.recordId}`;
      default:
        return "#";
    }
  };

  return (
    <div
      style={{
        position: "absolute",
        top: "20px",
        right: "20px",
        background: "white",
        padding: "20px",
        borderRadius: "10px",
        boxShadow: "0 4px 15px rgba(0,0,0,0.2)",
        width: "300px",
        zIndex: 100,
        fontFamily: "Poppins, sans-serif",
      }}
    >
      <button
        onClick={onClose}
        style={{
          position: "absolute",
          top: "10px",
          right: "10px",
          background: "transparent",
          border: "none",
          fontSize: "24px",
          cursor: "pointer",
          lineHeight: "1",
          padding: "0",
          color: "#aaa",
        }}
      >
        &times;
      </button>
      <h3 style={{ marginTop: 0, marginBottom: "10px", paddingRight: "20px" }}>
        {node.name}
      </h3>
      {node.description && (
        <p style={{ fontSize: "14px", margin: "0 0 20px 0" }}>
          {node.description}
        </p>
      )}
      <a
        href={getSoftrUrl()}
        target="_blank"
        rel="noopener noreferrer"
        style={{ textDecoration: "none", display: "block" }}
      >
        <button
          style={{
            width: "100%",
            padding: "12px",
            border: "none",
            borderRadius: "5px",
            background: "black",
            color: "white",
            fontFamily: "Poppins-Light, sans-serif",
            cursor: "pointer",
            fontSize: "16px",
          }}
        >
          View Details
        </button>
      </a>
    </div>
  );
};

// ==================================================================
// Main App Component
// ==================================================================
const GraphApp = () => {
  const [graphData, setGraphData] = useState({ nodes: [], links: [] });
  const [selectedNode, setSelectedNode] = useState(null);

  // Receive data via postMessage from parent Softr app
  useEffect(() => {

    const handleDataMessage = (event) => {
      // Security check
      if (event.origin !== "https://cortex-knowledge-hub.softr.app") {
        return;
      }

      const receivedData = event.data;

      debugLog("Data received from Softr:", receivedData);

      if (receivedData && Array.isArray(receivedData)) {
        const processedData = processAirtableData(receivedData);
        setGraphData(processedData);
      }
    };

    window.addEventListener("message", handleDataMessage);

    return () => {
      window.removeEventListener("message", handleDataMessage);
    };
  }, []); // The empty array ensures this runs only once on startup

  return (
    <div
      style={{
        height: "100vh",
        width: "100vw",
        background: "#f8f9fa",
        position: "relative",
      }}
    >
      {selectedNode && (
        <InfoPopup node={selectedNode} onClose={() => setSelectedNode(null)} />
      )}

      <Canvas
        camera={{ position: [250, 700, 450], fov: 50, near: 1, far: 10000 }}
      >
        <ambientLight intensity={1.5} />
        <directionalLight position={[200, 500, 200]} intensity={1} />
        <gridHelper
          args={[2000, 40, 0xdddddd, 0xdddddd]}
          position={[0, -0.1, 0]}
        />

        <GraphScene graphData={graphData} onNodeClick={setSelectedNode} />

        <MapControls
          enableRotate={false}
          minDistance={200}
          maxDistance={2000}
        />
      </Canvas>
    </div>
  );
};

export default GraphApp;
